import Storage from'../core/storage.js';import Utils from'../core/utils.js';const DragDropTesters={STORAGE_KEY:'redis-acl-builder-tester-order',DEFAULT_ORDER:['command-tester-panel','keyspace-tester-panel','integrated-tester-panel'],state:{isInitialized:false,isDragging:false,draggedTester:null,draggedIndex:-1,dropZoneIndex:-1,testerOrder:[],originalPositions:new Map(),mouseX:0,mouseY:0,dragStartX:0,dragStartY:0,testerStartX:0,testerStartY:0,lastDetectionTime:0},elements:{testingContainer:null,testers:[],dragHandles:[]},init(){try{this.findElements();this.loadTesterOrder();this.createDragHandles();this.applyTesterOrder();this.setupEventListeners();this.state.isInitialized=true;}catch(error){console.error('Failed to initialize drag-drop testers:',error);}},findElements(){this.elements.testingContainer=document.querySelector('.testing-container');if(!this.elements.testingContainer){throw new Error('Testing container not found');}
this.elements.testers=Array.from(this.elements.testingContainer.querySelectorAll('.test-section'));if(this.elements.testers.length<2){throw new Error(`Expected at least 2 testing sections, found ${this.elements.testers.length}`);}},loadTesterOrder(){if(window._initialTesterOrder&&Array.isArray(window._initialTesterOrder)&&window._initialTesterOrder.length>=2){this.state.testerOrder=[...window._initialTesterOrder];return;}
try{const saved=localStorage.getItem(this.STORAGE_KEY);if(saved){const savedOrder=JSON.parse(saved);if(Array.isArray(savedOrder)&&savedOrder.length>=2){this.state.testerOrder=savedOrder;return;}}}catch(error){console.warn('Failed to load tester order:',error);}
this.state.testerOrder=[...this.DEFAULT_ORDER];},saveTesterOrder(){try{localStorage.setItem(this.STORAGE_KEY,JSON.stringify(this.state.testerOrder));}catch(error){console.warn('Failed to save tester order:',error);}},createDragHandles(){this.elements.dragHandles=[];this.elements.testers.forEach(tester=>{const dragHandle=tester.querySelector('.tester-drag-handle');if(dragHandle){this.elements.dragHandles.push(dragHandle);}});},updateDragHandleReferences(){this.elements.dragHandles=[];this.elements.testers.forEach(tester=>{const dragHandle=tester.querySelector('.tester-drag-handle');if(dragHandle){this.elements.dragHandles.push(dragHandle);}});},applyTesterOrder(){this.state.originalPositions.clear();this.elements.testers.forEach((tester,index)=>{this.state.originalPositions.set(tester,index);});const reorderedTesters=[];this.state.testerOrder.forEach(testerId=>{const tester=this.elements.testers.find(t=>t.id===testerId);if(tester){reorderedTesters.push(tester);}});this.elements.testers.forEach(tester=>{if(!reorderedTesters.includes(tester)){reorderedTesters.push(tester);}});this.elements.testers=reorderedTesters;this.state.testerOrder=this.elements.testers.map(t=>t.id);this.updateCSSOrderProperties();},updateCSSOrderProperties(){this.state.testerOrder.forEach((testerId,index)=>{document.documentElement.style.setProperty(`--${testerId}-order`,index);});},setupEventListeners(){this.setupDragHandleListeners();this.setupGlobalListeners();this.setupTesterHoverListeners();},setupDragHandleListeners(){this.elements.dragHandles.forEach((handle,index)=>{const newHandle=handle.cloneNode(true);handle.parentNode.replaceChild(newHandle,handle);this.elements.dragHandles[index]=newHandle;});this.elements.dragHandles.forEach((handle,index)=>{handle.addEventListener('dragstart',(e)=>{e.preventDefault();});handle.addEventListener('mousedown',(e)=>{e.preventDefault();const currentTesterIndex=this.findCurrentTesterIndex(handle);this.handleMouseDown(e,currentTesterIndex);});});},setupGlobalListeners(){document.addEventListener('mousemove',(e)=>{if(this.state.isDragging){this.handleMouseMove(e);}});document.addEventListener('mouseup',(e)=>{if(this.state.isDragging){this.handleMouseUp(e);}});},setupTesterHoverListeners(){this.elements.testingContainer.addEventListener('mousemove',(e)=>{if(this.state.isDragging){this.detectDropZone(e);}});},findCurrentTesterIndex(handle){const parentTester=handle.closest('.test-section');if(!parentTester)return-1;return this.elements.testers.findIndex(tester=>tester===parentTester);},handleMouseDown(e,index){this.state.isDragging=true;this.state.draggedIndex=index;this.state.draggedTester=this.elements.testers[index];const rect=this.state.draggedTester.getBoundingClientRect();this.state.dragStartX=e.clientX;this.state.dragStartY=e.clientY;this.state.testerStartX=rect.left;this.state.testerStartY=rect.top;this.state.draggedTester.classList.add('tester-dragging');document.body.classList.add('tester-drag-active');document.body.style.userSelect='none';},handleMouseMove(e){if(!this.state.isDragging||!this.state.draggedTester)return;this.state.mouseX=e.clientX;this.state.mouseY=e.clientY;const deltaX=e.clientX-this.state.dragStartX;const deltaY=e.clientY-this.state.dragStartY;this.state.draggedTester.style.transform=`
            translateX(${12 + deltaX}px)
            translateY(${-12 + deltaY}px)
            scale(1.02)
        `;},detectDropZone(e){const draggedIndex=this.state.draggedIndex;if(!this.state.draggedTester)return;const now=Date.now();if(now-this.state.lastDetectionTime<16)return;this.state.lastDetectionTime=now;const draggedRect=this.state.draggedTester.getBoundingClientRect();const draggedMidpoint=draggedRect.left+(draggedRect.width/2);const testerRects=this.elements.testers.map((tester,index)=>{if(index===draggedIndex)return null;return{index,rect:tester.getBoundingClientRect(),element:tester};}).filter(t=>t!==null);let insertPosition=draggedIndex;const crossovers=[];for(const testerData of testerRects){const{index,rect}=testerData;const targetMidpoint=rect.left+(rect.width/2);if(draggedIndex<index){if(draggedMidpoint>targetMidpoint){crossovers.push(index);}}else{if(draggedMidpoint<targetMidpoint){crossovers.push(index);}}}
if(crossovers.length>0){if(draggedIndex<Math.max(...crossovers)){insertPosition=Math.max(...crossovers);}else{insertPosition=Math.min(...crossovers);}}
if(insertPosition!==this.state.dropZoneIndex){this.state.dropZoneIndex=insertPosition;this.visualizeInsertion(draggedIndex,insertPosition);}},visualizeInsertion(draggedIndex,insertPosition){const currentOrder=[...this.elements.testers];const previewOrder=[...currentOrder];if(insertPosition!==draggedIndex){const draggedTester=previewOrder.splice(draggedIndex,1)[0];previewOrder.splice(insertPosition,0,draggedTester);}
this.elements.testers.forEach((tester,currentIndex)=>{if(currentIndex===draggedIndex)return;const previewIndex=previewOrder.findIndex(t=>t===tester);const positionDifference=previewIndex-currentIndex;if(!tester.classList.contains('tester-preview-position')){tester.classList.add('tester-preview-position');}
if(positionDifference!==0){const testerWidth=tester.getBoundingClientRect().width;const gap=16;const calculatedOffset=positionDifference*(testerWidth+gap);tester.style.transform=`translateX(${calculatedOffset}px)`;}else{tester.style.transform='translateX(0px)';}});},handleMouseUp(e){if(!this.state.isDragging)return;if(this.state.dropZoneIndex!==-1&&this.state.dropZoneIndex!==this.state.draggedIndex){this.insertTester(this.state.draggedIndex,this.state.dropZoneIndex);Utils.showNotification('Testing section layout updated! 🔄','success');}
this.handleDragEnd();},handleDragEnd(){if(!this.state.isDragging)return;this.elements.testers.forEach(tester=>{tester.classList.remove('tester-dragging','tester-drop-zone','tester-swap-animation','tester-make-room-left','tester-make-room-right','tester-preview-position');tester.style.transform='';});document.body.classList.remove('tester-drag-active');document.body.style.userSelect='';this.state.isDragging=false;this.state.draggedTester=null;this.state.draggedIndex=-1;this.state.dropZoneIndex=-1;},insertTester(draggedIndex,insertPosition){const container=this.elements.testingContainer;const draggedTester=this.elements.testers[draggedIndex];const draggedTesterId=this.state.testerOrder.splice(draggedIndex,1)[0];const draggedTesterElement=this.elements.testers.splice(draggedIndex,1)[0];this.state.testerOrder.splice(insertPosition,0,draggedTesterId);this.elements.testers.splice(insertPosition,0,draggedTesterElement);this.elements.testers.forEach(tester=>tester.classList.add('tester-swap-animation'));this.updateCSSOrderProperties();this.saveTesterOrder();setTimeout(()=>{this.elements.testers.forEach(tester=>{tester.classList.remove('tester-swap-animation');});},300);},resetToDefault(){this.state.testerOrder=[...this.DEFAULT_ORDER];this.applyTesterOrder();this.saveTesterOrder();Utils.showNotification('Testing section layout reset to default! 🔄','success');},getCurrentOrder(){return[...this.state.testerOrder];}};export default DragDropTesters;